/**
 *  One user action from the transfer center. Retry is a new attempt that
 *  reuses the same transfer id so a receiver can resume from its checkpoint.
 */
export type TransferAction = "pause" | "resume" | "cancel" | "retry";

export type TransferDirection = "send" | "receive";

export type TransferEvent = 
/**  An incoming offer that needs the user's approval before it can start. */
{ type: "offered"; transfer_id: string; device_id: string; device_name: string; file_name: string; file_size: number; total_files: number } | 
/**  A send that is waiting for a free active-transfer slot. */
{ type: "queued"; transfer_id: string; device_id: string; device_name: string; file_name: string; total_files: number; total_bytes: number } | { type: "prepared"; transfer_id: string; device_id: string; device_name: string; file_name: string; total_files: number; total_bytes: number } | 
/**  Throttled to at most one event per 100 ms by the runtime. */
{ type: "progress"; transfer_id: string; bytes_done: number; bytes_total: number; bytes_per_second: number } | { type: "paused"; transfer_id: string } | { type: "resumed"; transfer_id: string } | { type: "completed"; transfer_id: string } | { type: "cancelled"; transfer_id: string } | { type: "failed"; transfer_id: string; code: string; message: string; retryable: boolean } | { type: "file_access_required"; transfer_id: string; file_id: string } | 
/**  The window drag state changed; drives the drop overlay. */
{ type: "drag_hover"; active: boolean } | 
/**
 *  Files were dropped on the window. Only opaque handles and base names
 *  cross this boundary; the local paths stay in the Rust registry.
 */
{ type: "files_dropped"; files: RegisteredFileView[]; 
/**  Dropped folders, already scanned and described. They become batches. */
folders: RegisteredFolderView[]; rejected: string[]; 
/**  Dropped paths beyond the per-batch limits. */
skipped: number };

export type TransferState = 
/**  An incoming offer that is waiting for the user's decision. */
"offered" | 
/**  A send that is waiting for a free active-transfer slot. */
"queued" | 
/**
 *  Left over from a previous run: the checkpoint is on disk but nothing is
 *  driving it, so the user can decide to retry or drop it.
 */
"interrupted" | "preparing" | "transferring" | "paused" | "completed" | "failed" | "cancelled";

export type TransferSummary = {
	transfer_id: string,
	device_id: string,
	device_name: string,
	direction: TransferDirection,
	state: TransferState,
	file_name: string,
	bytes_total: number,
	bytes_done: number,
	bytes_per_second: number,
	total_files: number,
	error_code: string | null,
	error_code_number: number | null,
	error_message: string | null,
	retryable: boolean,
	created_at_ms: number,
	updated_at_ms: number,
	/**
	 *  Set when this transfer is one file of a folder batch. The UI groups by
	 *  it and never needs the entries themselves.
	 */
	batch_id: string | null,
	/**  Display name of the batch root directory. */
	batch_root: string | null,
	/**  This file's path inside the batch root. */
	relative_path: string | null,
};

export type TrustEvent = { type: "added"; peer: PeerSummary } | { type: "updated"; peer: PeerSummary } | { type: "removed"; device_id: string };

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

